<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { get } from '@/api/request'
import LocalSession from '@/features/versions/LocalSession.vue'
import { getLocalContext, errorMessage } from '@/features/versions/api'
import type { FinalSnapshot, FinalVersion } from '@/features/final-review/api'
import FinalGraphPreview from '@/features/final-review/FinalGraphPreview.vue'
interface Row {version:FinalVersion;document:{title:string;caseNumber?:string;sourceType:string};guideVersion:{versionCode:string}}
interface Detail {graphView:import('@/types/graph').GraphView;snapshot:FinalSnapshot;document:Row['document'];guideVersion:Row['guideVersion'];labelDistribution:{definitionId:string;code:string;name:string;count:number}[];relationDistribution:{definitionId:string;code:string;name:string;count:number}[];agreement:{score:number;reproducible:boolean;notice?:string;calculationId?:string}}
const rows=ref<Row[]>([]), detail=ref<Detail>(), total=ref(0),page=ref(1),source=ref(''),error=ref(''),loading=ref(false)
async function load(){loading.value=true;error.value='';detail.value=undefined;try{if(!import.meta.env.DEV)throw new Error('成果查询试行接口待团队评审后正式接入');await getLocalContext();const r=await get<{data:{items:Row[]};meta:{total:number}}>('/api/local/member-d/results',{page:page.value,size:20,...(source.value?{sourceType:source.value}:{})},{baseURL:'',_withMeta:true});rows.value=r.data.items;total.value=r.meta.total;}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
async function show(id:string){error.value='';try{detail.value=await get<Detail>(`/api/local/member-d/results/${id}`,undefined,{baseURL:''})}catch(e){error.value=errorMessage(e)}}
onMounted(load)
</script>
<template><LocalSession description="已入库成果查询试行；只读取当前授权范围内的固定最终版本"/><div class="page-head between"><div><div class="eyebrow">RESEARCH RESULTS</div><h1 class="t-h1">已入库成果</h1><p class="muted">检索最终成果，核查结构化要素、关系及来源。</p></div><router-link class="btn btn-primary" to="/export">导出成果</router-link></div><div class="note warn">D 分支试行，公共查询模型待团队评审；图示按冻结快照只读构建，覆盖全部结构。</div><div v-if="error" class="note danger" role="alert">{{ error }}</div>
<section class="card"><div class="card-head between"><select class="select" aria-label="成果来源" v-model="source" @change="page=1;load()"><option value="">全部来源</option><option value="ORDINARY_JUDGMENT">普通裁判文书</option><option value="GUIDING_CASE">指导性案例</option><option value="REFERENCE_CASE">参考案例</option></select><button class="btn btn-secondary" :disabled="loading" @click="load">刷新</button></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>文书 / 案号</th><th>最终版</th><th>指南</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.version.id"><td>{{ r.document.title }}<p class="muted t-xs">{{ r.document.caseNumber }}</p></td><td>F{{ r.version.versionNumber }}</td><td>{{ r.guideVersion.versionCode }}</td><td><span class="badge success">已入库 · 只读</span></td><td><button class="btn btn-sm" @click="show(r.version.id)">完整详情</button></td></tr><tr v-if="!rows.length"><td colspan="5" class="empty muted">{{ loading?'读取中…':'当前授权范围内没有已入库成果' }}</td></tr></tbody></table></div><div class="card-foot between"><button class="btn btn-sm" :disabled="page<=1" @click="page--;load()">上一页</button><span>{{ page }} 页 · 共 {{ total }} 条</span><button class="btn btn-sm" :disabled="page*20>=total" @click="page++;load()">下一页</button></div></section>
<template v-if="detail"><div class="page-head"><h2>{{ detail.document.title }} · F{{ detail.snapshot.version.versionNumber }}</h2><p class="mono t-xs">{{ detail.snapshot.version.id }}</p></div><section class="card"><div class="card-head"><b>全部要素</b></div><div class="tbl-wrap"><table class="tbl"><thead><tr><th>序号</th><th>完整文本</th><th>动态标签</th><th>位置</th></tr></thead><tbody><tr v-for="e in detail.snapshot.elements" :key="e.id"><td>{{ e.displayNo||'非命题' }}</td><td class="text">{{ e.text }}</td><td>{{ e.labelCode }}</td><td>[{{ e.startOffset }}, {{ e.endOffset }})</td></tr></tbody></table></div></section><FinalGraphPreview :snapshot="detail.snapshot" :graph="detail.graphView"/><div class="grid-2 panels"><section class="card"><div class="card-head"><b>标签分布</b></div><div class="card-body"><p v-for="d in detail.labelDistribution" :key="d.definitionId" class="between"><span>{{ d.code }} {{ d.name }}</span><b>{{ d.count }}</b></p></div></section><section class="card"><div class="card-head"><b>关系分布</b></div><div class="card-body"><p v-for="d in detail.relationDistribution" :key="d.definitionId" class="between"><span>{{ d.code }} {{ d.name }}</span><b>{{ d.count }}</b></p></div></section></div><section class="card"><div class="card-body"><p>切割一致性：{{ (detail.agreement.score*100).toFixed(2) }}%</p><p v-if="detail.agreement.reproducible" class="mono">真实计算记录：{{ detail.agreement.calculationId }}</p><p v-else class="muted">{{ detail.agreement.notice }}</p><details><summary>完整关系、参与项及来源</summary><pre>{{ JSON.stringify({relations:detail.snapshot.relations,participants:detail.snapshot.participants,provenance:detail.snapshot.version.provenance},null,2) }}</pre></details></div></section></template>
</template>
<style scoped>.note,.panels{margin:20px 0}.page-head{margin-top:20px}.select{max-width:220px}.empty{padding:60px 20px;text-align:center}.text{white-space:pre-wrap;max-width:650px}.mono{overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}.card-body p{margin:10px 0}@media(max-width:850px){.panels{grid-template-columns:1fr}}</style>
